"""
espzero/_wifi.py
WiFi class for ESP32 — wraps the network module in a picozero-style API.
"""
from . import _hal


class WiFi:
    """
    Wraps ESP32 WiFi (station mode) in a simple, picozero-style interface.

    Usage::

        from espzero import WiFi
        wifi = WiFi()
        ip = wifi.connect("MySSID", "password")
        print("Connected:", ip)
    """

    def __init__(self):
        import network
        self._sta = network.WLAN(network.STA_IF)

    def connect(self, ssid, password, timeout=20):
        """
        Connect to the given access point.

        Blocks until connected (up to *timeout* seconds, default 20) then returns the
        assigned IP address string. Raises ``OSError`` on timeout.

        Also sets the HAL ``_wifi_active`` flag so that any subsequent call to
        ``make_adc()`` with an ADC2 pin will print a warning.

        :param str ssid: Network name (SSID). Note: ESP32 requires 2.4GHz Wi-Fi.
        :param str password: Network password.
        :param int timeout: Maximum seconds to wait for connection. Default 20.
        :returns: IP address string.
        :raises OSError: If the connection times out.
        """
        import time
        if not self._sta.active():
            self._sta.active(True)
            time.sleep(0.2)

        # Reset any stale connection state
        try:
            self._sta.disconnect()
            time.sleep(0.1)
        except Exception:
            pass

        print("[espzero] Connecting to WiFi '{}' (2.4GHz)...".format(ssid), end="")
        self._sta.connect(ssid, password)
        start = time.time()
        last_dot = start
        while not self._sta.isconnected():
            now = time.time()
            if now - last_dot >= 1.0:
                print(".", end="")
                last_dot = now

            if now - start > timeout:
                print(" Failed!")
                status_msg = ""
                try:
                    stat = self._sta.status()
                    import network
                    if hasattr(network, 'STAT_WRONG_PASSWORD') and stat == network.STAT_WRONG_PASSWORD:
                        status_msg = " (Reason: Wrong password)"
                    elif hasattr(network, 'STAT_NO_AP_FOUND') and stat == network.STAT_NO_AP_FOUND:
                        status_msg = " (Reason: SSID not found - ensure it is 2.4GHz, not 5GHz)"
                except Exception:
                    pass
                raise OSError("[espzero] WiFi connection timed out ({}s).{}".format(timeout, status_msg))
            time.sleep(0.1)

        print(" Connected!")
        _hal._wifi_active = True
        print("[espzero] WiFi connected. IP:", self._sta.ifconfig()[0])
        print("[espzero] NOTE: ADC2 pins are unavailable while WiFi is active.")
        return self._sta.ifconfig()[0]

    def disconnect(self):
        """Disconnect from the current access point."""
        self._sta.disconnect()
        _hal._wifi_active = False

    def scan(self):
        """
        Scan for nearby access points.

        :returns: List of tuples ``(ssid, bssid, channel, rssi, authmode, hidden)``.
        """
        self._sta.active(True)
        return self._sta.scan()

    @property
    def is_connected(self):
        """``True`` if currently connected to an access point."""
        return self._sta.isconnected()

    @property
    def ip(self):
        """Current IP address, or ``None`` if not connected."""
        return self._sta.ifconfig()[0] if self.is_connected else None

    @property
    def ifconfig(self):
        """Full interface config tuple ``(ip, mask, gateway, dns)``."""
        return self._sta.ifconfig()
